const D = { energy: .55, scale: 1, density: .5, speed: 1, wear: .4, hue: 28, x: .5, y: .44, style: 'herringbone', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- A waxed parquet floor running away to the vanishing point. The pattern is the SUBJECT:
// which way each block's grain runs is what draws it — herringbone, chevron, basketweave, a
// Versailles panel. Because the grain direction changes block to block, the same overhead
// light reads bright on one block and dull on its neighbour: that anisotropic flip is what
// makes wood look like wood, and it is why parquet shimmers when you walk on it.
// ONLY BELOW THE HORIZON — above stays fully transparent so the bg slot shows through. ----

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), sd = P.seed|0;
function hsh(ix,iy){ let h=(Math.imul(ix,374761393)+Math.imul(iy,668265263)+Math.imul(sd,1442695041))|0;
  h=Math.imul(h^(h>>>13),1274126177)|0; return ((h^(h>>>16))>>>0)/4294967295; }   // >>> : a >> fold caps the hash at 0.5
function vn(x,y){ const ix=Math.floor(x), iy=Math.floor(y), fx=x-ix, fy=y-iy;
  const wx=fx*fx*(3-2*fx), wy=fy*fy*(3-2*fy);
  const a=hsh(ix,iy), b=hsh(ix+1,iy), c=hsh(ix,iy+1), d=hsh(ix+1,iy+1);
  return a+(b-a)*wx+(c-a)*wy+(a-b-c+d)*wx*wy; }
function fbm(x,y){ return .55*vn(x,y)+.28*vn(x*2.03+5.1,y*2.03-3.3)+.17*vn(x*4.07-2.7,y*4.07+7.9); }
function hsv(h,s,v){ h=(((h%360)+360)%360)/60; const c=v*s, xx=c*(1-Math.abs(h%2-1)), m=v-c;
  let r,g2,b2;
  if(h<1){r=c;g2=xx;b2=0}else if(h<2){r=xx;g2=c;b2=0}else if(h<3){r=0;g2=c;b2=xx}
  else if(h<4){r=0;g2=xx;b2=c}else if(h<5){r=xx;g2=0;b2=c}else{r=c;g2=0;b2=xx}
  return [(r+m)*255,(g2+m)*255,(b2+m)*255]; }

const sty = P.style, en = cl(P.energy,0,1), wr = cl(P.wear,0,1);
const Hh = ((P.hue%360)+360)%360, tt = K.t;
const bp = sty==='blueprint', chev = sty==='chevron', bask = sty==='basketweave', vers = sty==='versailles';

// ---- camera ----
const vy = cl(P.y,.18,.78)*height, vx = cl(P.x,.05,.95)*width;
const f = u*.92, H0 = 1;
const BL = .16*cl(P.scale,.35,2.4);          // block length in world units
const BWd = BL*.30;                          // block width

// ---- perpetual scroll ----
if (S.z == null) S.z = 0;
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.z += dt * P.speed * (.13 + .18*K.intensity) * (.55 + .6*en);
const zoff = S.z;

const bass = (S.b = (S.b||0)*.82 + (A.bass||0)*.18);
// two windows' worth of light drifting across the floor on incommensurate rates
const l1x = 1.6*Math.sin(tt*.073) + .7*Math.sin(tt*.181+1.3);
const l1z = 3.4 + 2.0*Math.sin(tt*.051+.7) + .9*Math.sin(tt*.139+2.1);
const l2x = -1.9*Math.sin(tt*.101+2.2) - .6*Math.sin(tt*.241);
const l2z = 5.8 + 2.6*Math.sin(tt*.039+1.9) + 1.2*Math.sin(tt*.173+.4);
const glow = (.40+.60*en)*(.55+.5*K.intensity) + bass*.28;

// ---- palette: species ----
let woodD, woodL, jointC, sheenC;
if (bp)   { woodD=[212,74,14]; woodL=[190,44,80]; jointC=[214,80,7];  sheenC=[186,50,94]; }
else if (sty==='ebony'){ woodD=[Hh+8,26,10]; woodL=[Hh+2,16,46]; jointC=[Hh+10,32,5]; sheenC=[Hh-4,8,92]; }
else      { woodD=[Hh-6,56,24]; woodL=[Hh+6,42,80]; jointC=[Hh-10,54,12]; sheenC=[Hh+12,14,98]; }
const cWd = hsv(woodD[0], woodD[1]/100, woodD[2]/100);
const cWl = hsv(woodL[0], woodL[1]/100, woodL[2]/100);
const cJt = hsv(jointC[0], jointC[1]/100, jointC[2]/100);
const cSh = hsv(sheenC[0], sheenC[1]/100, sheenC[2]/100);

const BWb = 176, BHb = Math.max(44, Math.round(BWb*height/width));
if (!S.g || S.bk !== BWb+'x'+BHb){ if(S.g){ try{S.g.remove();}catch(e){} }
  S.g = createGraphics(BWb,BHb); S.g.pixelDensity(1); S.bk = BWb+'x'+BHb; }
const g = S.g; g.loadPixels(); const px = g.pixels;

const AL = P.alpha/100;
const j0 = Math.max(0, Math.floor((vy/height)*BHb));
for (let j=0;j<j0;j++) for (let i=0;i<BWb;i++) px[4*(j*BWb+i)+3] = 0;

// Resolve which block a world point falls in, and which way its grain runs.
// Returns [blockId, u_along_grain, v_across_grain, grainAngle]
function blockAt(X, Z){
  if (chev){
    // chevron: blocks mitred so the grain zig-zags in continuous Vs
    const col = Math.floor(X/BWd);
    const dir = (col & 1) ? 1 : -1;
    const skew = Z + dir*X;                     // shear along the grain direction
    const row = Math.floor(skew/BL);
    return [col*911 + row*17, (skew/BL)-row, (X/BWd)-col, dir*.785];
  }
  if (bask){
    // basketweave: alternating pairs of blocks, laid at 90 degrees
    const cell = BL;
    const cxi = Math.floor(X/cell), czi = Math.floor(Z/cell);
    const flip = ((cxi + czi) & 1);
    const fx = X/cell - cxi, fz = Z/cell - czi;
    if (flip){ const sub = Math.floor(fz*3); return [cxi*733+czi*29+sub, fx, fz*3-sub, 0]; }
    const sub = Math.floor(fx*3); return [cxi*733+czi*29+sub+7, fz, fx*3-sub, 1.5708];
  }
  if (vers){
    // Versailles panel: a large square panel of diagonal weave, bordered by a running frame
    const pan = BL*3.2;
    const pxi = Math.floor(X/pan), pzi = Math.floor(Z/pan);
    const fx = X/pan - pxi, fz = Z/pan - pzi;
    const br = .12;
    if (fx<br || fx>1-br || fz<br || fz>1-br){   // the border frame: grain runs along it
      const along = (fx<br||fx>1-br) ? 1.5708 : 0;
      return [pxi*577+pzi*41+99, (along? fz:fx)*6, ((along? fx:fz))*8, along];
    }
    // interior: diagonal herringbone at 45
    const dx2 = (fx-.5)+(fz-.5), dz2 = (fx-.5)-(fz-.5);
    const col = Math.floor(dx2/(BWd/pan));
    const row = Math.floor((dz2 + ((col&1)?.5:0)*(BL/pan))/(BL/pan));
    return [pxi*577+pzi*41+col*13+row*7, (dz2/(BL/pan))-row, (dx2/(BWd/pan))-col, (col&1)?.785:-.785];
  }
  // herringbone (default): blocks at 90 to each other, stepping along the diagonal
  const s2 = .70710678;
  const a = (X + Z)*s2, b = (Z - X)*s2;         // rotate 45 so the pattern runs true
  const ai = Math.floor(a/BL), bi = Math.floor(b/BL);
  const fa = a/BL - ai, fb = b/BL - bi;
  // within each BL cell, one block lies along a, the next along b
  const par = ((ai + bi) & 1);
  if (par){ const sub = Math.floor(fb/(BWd/BL)); return [ai*401+bi*23+sub, fa, (fb/(BWd/BL))-sub, .785]; }
  const sub = Math.floor(fa/(BWd/BL)); return [ai*401+bi*23+sub+3, fb, (fa/(BWd/BL))-sub, -.785];
}

for (let j=j0;j<BHb;j++){
  const sy = (j+.5)/BHb*height, dy = sy - vy;
  if (dy < .35){ for (let i=0;i<BWb;i++) px[4*(j*BWb+i)+3] = 0; continue; }
  const Z = f*H0/dy, wz = Z + zoff;
  const far = cl((Z-1.1)/9, 0, 1);
  const det = cl(1 - far*1.05, .04, 1);
  for (let i=0;i<BWb;i++){
    const sx = (i+.5)/BWb*width, X = (sx-vx)*Z/f;
    const o = 4*(j*BWb+i);
    const B = blockAt(X, wz);
    const id = B[0], ua = B[1], va = B[2], ang = B[3];
    const q = hsh(id*7+1, id*13+5);              // per-block species lottery
    // ---- grain: rings running ALONG the block. Cathedral figure where the cut wanders. ----
    const gx = ua*7.0, gy = va*1.4 + q*40;
    const ring = fbm(gx*.9 + q*17, gy*5.5);
    const fig = .5+.5*Math.sin(ring*13 + gy*2.1 + Math.sin(gx*1.3)*2.2);
    const grain = (fig*.55 + fbm(gx*22, gy*30)*.45)*det + (1-det)*.5;
    // ---- joint between blocks ----
    const edge = Math.min(Math.min(ua-Math.floor(ua), 1-(ua-Math.floor(ua))),
                          Math.min(va, 1-va));
    const jw = .045 + wr*.035;
    const jt = cl(1 - edge/jw, 0, 1);
    // ---- anisotropic sheen: THE parquet effect. A block's grain direction decides how it
    // catches the light, so neighbours at 90 degrees flip bright/dull under the same lamp. ----
    const toL1x = l1x - X, toL1z = l1z - (wz-zoff);
    const dl1 = Math.sqrt(toL1x*toL1x + toL1z*toL1z)+1e-3;
    const toL2x = l2x - X, toL2z = l2z - (wz-zoff);
    const dl2 = Math.sqrt(toL2x*toL2x + toL2z*toL2z)+1e-3;
    const gvx = Math.cos(ang), gvz = Math.sin(ang);   // the grain direction in world space
    // light along the grain scatters down the fibres (dull); across it, it glints (bright)
    const al1 = Math.abs((toL1x/dl1)*gvx + (toL1z/dl1)*gvz);
    const al2 = Math.abs((toL2x/dl2)*gvx + (toL2z/dl2)*gvz);
    const pool1 = Math.exp(-dl1*dl1*.09), pool2 = Math.exp(-dl2*dl2*.06)*.75;
    const aniso = pool1*(1-al1*.78) + pool2*(1-al2*.78);
    let lum = (.42 + q*.18) * (.68 + grain*.58) * (1 + aniso*glow*2.1);
    lum *= 1 - jt*.55;
    // wax sheen + wear: traffic lanes are dulled and scuffed
    const lane = cl(1-Math.abs(X)/1.5, 0, 1)*wr;
    lum *= 1 - lane*(.16 + fbm(X*3.1, wz*3.1)*.14);
    lum = cl(lum, 0, 1.5);
    let r = cWd[0]+(cWl[0]-cWd[0])*lum, g2 = cWd[1]+(cWl[1]-cWd[1])*lum, b2 = cWd[2]+(cWl[2]-cWd[2])*lum;
    r += (cJt[0]-r)*jt*.80; g2 += (cJt[1]-g2)*jt*.80; b2 += (cJt[2]-b2)*jt*.80;
    // the specular streak the wax throws back at you
    const spec = Math.pow(cl(aniso,0,1), 1.6)*glow*(.55+en*.7);
    r += (cSh[0]-r)*spec*.42; g2 += (cSh[1]-g2)*spec*.42; b2 += (cSh[2]-b2)*spec*.42;
    if (bp){
      const on = jt > .34 ? 1 : 0;
      const v2 = .12+.10*(1-far);
      r = on? 80 : v2*40; g2 = on? 204*det+36 : v2*104; b2 = on? 250 : v2*176;
    }
    const hazeK = far*far*.85;
    const hc = bp? [40,120,190] : [cWl[0]*.66, cWl[1]*.68, cWl[2]*.78];
    r += (hc[0]-r)*hazeK; g2 += (hc[1]-g2)*hazeK; b2 += (hc[2]-b2)*hazeK;
    px[o]=cl(r,0,255); px[o+1]=cl(g2,0,255); px[o+2]=cl(b2,0,255);
    px[o+3] = 255*AL*cl(1-far*far*.72, 0, 1)*cl(dy/2.2, 0, 1);
  }
}
g.updatePixels();
push();
image(g,0,0,width,height);
pop();

// ---- dust turning in the light pools above the floor ----
push();
blendMode(ADD);
noStroke();
const dens = cl(P.density,0,1);
const NM = Math.round(6 + dens*44);
for (let i=0;i<NM;i++){
  const f1 = hsh(i*17+7, 3), f2 = hsh(i*17+8, 5), f3 = hsh(i*17+9, 11);
  const mz = ((f2 + tt*(.012+f3*.05)*P.speed) % 1.05);
  const my = vy + Math.pow(mz,2.0)*(height-vy)*1.0;
  const mx = (f1 + Math.sin(tt*(.14+f3*.33)+f1*6.28)*.045
                 + Math.sin(tt*(.05+f2*.12))*.028)*width;
  const sz = u*(.0014+f3*.0046)*(.4+mz*1.7);
  fill(sheenC[0], bp?40:10, 100, (6+f3*12)*(.3+en)*AL*(1-mz*.35));
  ellipse(mx, my, sz, sz*.8);
}
